values
  ('f5992c28-5027-45a5-9fcd-4668236c352b', 'debedfa1-d192-4f4a-8b51-cabf50445b5d', null, 'topic'::public.curated_course_node_type, 'Formalism consolidation', 'This module establishes formalism consolidation as the course''s first working framework. It supplies the language and representations needed before the path advances to time-independent perturbation i.', 0),
  ('e3f5c46b-878e-40ee-9cb9-29129440ac06', 'debedfa1-d192-4f4a-8b51-cabf50445b5d', 'f5992c28-5027-45a5-9fcd-4668236c352b', 'subtopic'::public.curated_course_node_type, 'Symmetries', 'Symmetries identifies a specific object, distinction, or relationship within formalism consolidation. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before conserved quantities because that next topic assumes this starting point.', 0),
  ('2a08a514-1665-42aa-9401-7acdd0a64be5', 'debedfa1-d192-4f4a-8b51-cabf50445b5d', 'f5992c28-5027-45a5-9fcd-4668236c352b', 'subtopic'::public.curated_course_node_type, 'Conserved quantities', 'Conserved quantities identifies a specific object, distinction, or relationship within formalism consolidation. Learners need to recognize and use it before combining this module''s ideas in later work. After symmetries, conserved quantities supplies what is needed to address pictures of time evolution.', 1),
  ('933d02c4-1e4f-49c0-a920-a58fa61c5218', 'debedfa1-d192-4f4a-8b51-cabf50445b5d', 'f5992c28-5027-45a5-9fcd-4668236c352b', 'subtopic'::public.curated_course_node_type, 'Pictures of time evolution', 'Pictures of time evolution identifies a specific object, distinction, or relationship within formalism consolidation. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, pictures of time evolution carries the completed idea into time-independent perturbation i.', 2),
  ('8826db29-35d6-462e-b372-0b0be99f24fc', 'debedfa1-d192-4f4a-8b51-cabf50445b5d', null, 'topic'::public.curated_course_node_type, 'Time-independent perturbation I', 'This module builds directly on formalism consolidation and develops time-independent perturbation i. It belongs here because its methods and distinctions are prerequisites for time-independent perturbation ii.', 1),
  ('e4c08dae-f31a-458a-8281-7acd5c1e6a09', 'debedfa1-d192-4f4a-8b51-cabf50445b5d', '8826db29-35d6-462e-b372-0b0be99f24fc', 'subtopic'::public.curated_course_node_type, 'Nondegenerate theory', 'Nondegenerate theory identifies a specific object, distinction, or relationship within time-independent perturbation i. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before first/second-order shifts because that next topic assumes this starting point.', 0),
  ('05df6415-3efe-4d4c-91a6-381419a0d8a9', 'debedfa1-d192-4f4a-8b51-cabf50445b5d', '8826db29-35d6-462e-b372-0b0be99f24fc', 'subtopic'::public.curated_course_node_type, 'First/second-order shifts', 'First/second-order shifts identifies a specific object, distinction, or relationship within time-independent perturbation i. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, first/second-order shifts carries the completed idea into time-independent perturbation ii.', 1),
  ('71fc93a9-c199-4ed4-9a01-1ba51bbe6b48', 'debedfa1-d192-4f4a-8b51-cabf50445b5d', null, 'topic'::public.curated_course_node_type, 'Time-independent perturbation II', 'This module builds directly on time-independent perturbation i and develops time-independent perturbation ii. It belongs here because its methods and distinctions are prerequisites for variational method.', 2),
  ('154d0ad6-d31b-42e0-a1f6-4a1abf1fa798', 'debedfa1-d192-4f4a-8b51-cabf50445b5d', '71fc93a9-c199-4ed4-9a01-1ba51bbe6b48', 'subtopic'::public.curated_course_node_type, 'Degeneracy', 'Degeneracy identifies a specific object, distinction, or relationship within time-independent perturbation ii. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before fine structure because that next topic assumes this starting point.', 0),
  ('5da9bda0-4caa-4a21-919e-63388578c226', 'debedfa1-d192-4f4a-8b51-cabf50445b5d', '71fc93a9-c199-4ed4-9a01-1ba51bbe6b48', 'subtopic'::public.curated_course_node_type, 'Fine structure', 'Fine structure identifies a specific object, distinction, or relationship within time-independent perturbation ii. Learners need to recognize and use it before combining this module''s ideas in later work. After degeneracy, fine structure supplies what is needed to address stark/zeeman effects.', 1),
  ('f53bf67e-1b6d-46e7-92e7-4d43e1cbf4aa', 'debedfa1-d192-4f4a-8b51-cabf50445b5d', '71fc93a9-c199-4ed4-9a01-1ba51bbe6b48', 'subtopic'::public.curated_course_node_type, 'Stark/Zeeman effects', 'Stark/Zeeman effects identifies a specific object, distinction, or relationship within time-independent perturbation ii. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, stark/zeeman effects carries the completed idea into variational method.', 2),
  ('e95ba522-4aac-4208-9574-be0b2bfc9621', 'debedfa1-d192-4f4a-8b51-cabf50445b5d', null, 'topic'::public.curated_course_node_type, 'Variational method', 'This module builds directly on time-independent perturbation ii and develops variational method. It belongs here because its methods and distinctions are prerequisites for wkb approximation.', 3),
  ('5286e200-7e47-4f8c-8a09-002fe323c5f0', 'debedfa1-d192-4f4a-8b51-cabf50445b5d', 'e95ba522-4aac-4208-9574-be0b2bfc9621', 'subtopic'::public.curated_course_node_type, 'Bounds', 'Bounds identifies a specific object, distinction, or relationship within variational method. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before trial states because that next topic assumes this starting point.', 0),
  ('9f56f816-f76d-4bd0-ab00-73e97b36f90d', 'debedfa1-d192-4f4a-8b51-cabf50445b5d', 'e95ba522-4aac-4208-9574-be0b2bfc9621', 'subtopic'::public.curated_course_node_type, 'Trial states', 'Trial states identifies a specific object, distinction, or relationship within variational method. Learners need to recognize and use it before combining this module''s ideas in later work. After bounds, trial states supplies what is needed to address hydrogenic and molecular examples.', 1),
  ('8f10dc51-5c23-4538-9ec2-7461f91ec04d', 'debedfa1-d192-4f4a-8b51-cabf50445b5d', 'e95ba522-4aac-4208-9574-be0b2bfc9621', 'subtopic'::public.curated_course_node_type, 'Hydrogenic and molecular examples', 'Hydrogenic and molecular examples identifies a specific object, distinction, or relationship within variational method. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, hydrogenic and molecular examples carries the completed idea into wkb approximation.', 2),
  ('f7995ab1-8bd6-4007-9f3a-31cb13088ba5', 'debedfa1-d192-4f4a-8b51-cabf50445b5d', null, 'topic'::public.curated_course_node_type, 'WKB approximation', 'This module builds directly on variational method and develops wkb approximation. It belongs here because its methods and distinctions are prerequisites for time-dependent perturbation.', 4),
  ('6235e85b-4b9f-4c62-86aa-792f28596efd', 'debedfa1-d192-4f4a-8b51-cabf50445b5d', 'f7995ab1-8bd6-4007-9f3a-31cb13088ba5', 'subtopic'::public.curated_course_node_type, 'Connection formulas', 'Connection formulas identifies a specific object, distinction, or relationship within wkb approximation. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before tunneling because that next topic assumes this starting point.', 0),
  ('7bc1d0f0-46df-44b8-a5cb-2fabc267cfff', 'debedfa1-d192-4f4a-8b51-cabf50445b5d', 'f7995ab1-8bd6-4007-9f3a-31cb13088ba5', 'subtopic'::public.curated_course_node_type, 'Tunneling', 'Tunneling identifies a specific object, distinction, or relationship within wkb approximation. Learners need to recognize and use it before combining this module''s ideas in later work. After connection formulas, tunneling supplies what is needed to address semiclassical quantization.', 1),
  ('adc2a7ab-337b-4d4c-a6b9-3257d1773138', 'debedfa1-d192-4f4a-8b51-cabf50445b5d', 'f7995ab1-8bd6-4007-9f3a-31cb13088ba5', 'subtopic'::public.curated_course_node_type, 'Semiclassical quantization', 'Semiclassical quantization identifies a specific object, distinction, or relationship within wkb approximation. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, semiclassical quantization carries the completed idea into time-dependent perturbation.', 2),
  ('f51baf43-fe00-40ee-b759-baf6583e33ed', 'debedfa1-d192-4f4a-8b51-cabf50445b5d', null, 'topic'::public.curated_course_node_type, 'Time-dependent perturbation', 'This module builds directly on wkb approximation and develops time-dependent perturbation. It belongs here because its methods and distinctions are prerequisites for fermi’s golden rule and adiabaticity.', 5),
  ('85d4b4b9-0181-4be7-8251-b892ffddec66', 'debedfa1-d192-4f4a-8b51-cabf50445b5d', 'f51baf43-fe00-40ee-b759-baf6583e33ed', 'subtopic'::public.curated_course_node_type, 'Transition amplitudes', 'Transition amplitudes identifies a specific object, distinction, or relationship within time-dependent perturbation. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before selection rules because that next topic assumes this starting point.', 0),
  ('e6a30eb2-8f82-48ac-bbfb-1329690ac05b', 'debedfa1-d192-4f4a-8b51-cabf50445b5d', 'f51baf43-fe00-40ee-b759-baf6583e33ed', 'subtopic'::public.curated_course_node_type, 'Selection rules', 'Selection rules identifies a specific object, distinction, or relationship within time-dependent perturbation. Learners need to recognize and use it before combining this module''s ideas in later work. After transition amplitudes, selection rules supplies what is needed to address driven two-level systems.', 1),
  ('c47bdd1e-327c-45fc-9fe1-b2a2fe333ce1', 'debedfa1-d192-4f4a-8b51-cabf50445b5d', 'f51baf43-fe00-40ee-b759-baf6583e33ed', 'subtopic'::public.curated_course_node_type, 'Driven two-level systems', 'Driven two-level systems gives time-dependent perturbation a reusable representation for organizing assumptions, variables, and relationships before analysis begins. As the final topic in this module, driven two-level systems carries the completed idea into fermi’s golden rule and adiabaticity.', 2),
  ('30f27e18-b82b-4a5a-88b3-04ac89a72315', 'debedfa1-d192-4f4a-8b51-cabf50445b5d', null, 'topic'::public.curated_course_node_type, 'Fermi’s golden rule and adiabaticity', 'This module builds directly on time-dependent perturbation and develops fermi’s golden rule and adiabaticity. It belongs here because its methods and distinctions are prerequisites for identical particles.', 6),
  ('a1e7759d-932c-457a-a044-161be2f7fe5d', 'debedfa1-d192-4f4a-8b51-cabf50445b5d', '30f27e18-b82b-4a5a-88b3-04ac89a72315', 'subtopic'::public.curated_course_node_type, 'Continuum transitions', 'Continuum transitions identifies a specific object, distinction, or relationship within fermi’s golden rule and adiabaticity. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before slow change because that next topic assumes this starting point.', 0),
  ('d8f6ff35-bba3-486e-8fda-73fde993aa7d', 'debedfa1-d192-4f4a-8b51-cabf50445b5d', '30f27e18-b82b-4a5a-88b3-04ac89a72315', 'subtopic'::public.curated_course_node_type, 'Slow change', 'Slow change identifies a specific object, distinction, or relationship within fermi’s golden rule and adiabaticity. Learners need to recognize and use it before combining this module''s ideas in later work. After continuum transitions, slow change supplies what is needed to address geometric phase glimpse.', 1),
  ('7b146949-6891-456c-9f9f-5c0cbe855a20', 'debedfa1-d192-4f4a-8b51-cabf50445b5d', '30f27e18-b82b-4a5a-88b3-04ac89a72315', 'subtopic'::public.curated_course_node_type, 'Geometric phase glimpse', 'Geometric phase glimpse identifies a specific object, distinction, or relationship within fermi’s golden rule and adiabaticity. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, geometric phase glimpse carries the completed idea into identical particles.', 2),
  ('a3648dfc-6dd7-491f-a415-c189b342f5e4', 'debedfa1-d192-4f4a-8b51-cabf50445b5d', null, 'topic'::public.curated_course_node_type, 'Identical particles', 'This module builds directly on fermi’s golden rule and adiabaticity and develops identical particles. It belongs here because its methods and distinctions are prerequisites for many-particle structure.', 7),
  ('75889170-8566-4826-b219-20edad8f01b1', 'debedfa1-d192-4f4a-8b51-cabf50445b5d', 'a3648dfc-6dd7-491f-a415-c189b342f5e4', 'subtopic'::public.curated_course_node_type, 'Bosons/fermions', 'Bosons/fermions identifies a specific object, distinction, or relationship within identical particles. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before symmetrization because that next topic assumes this starting point.', 0),
  ('1eef76cf-9a5e-4201-a1f3-f3018b6ef694', 'debedfa1-d192-4f4a-8b51-cabf50445b5d', 'a3648dfc-6dd7-491f-a415-c189b342f5e4', 'subtopic'::public.curated_course_node_type, 'Symmetrization', 'Symmetrization identifies a specific object, distinction, or relationship within identical particles. Learners need to recognize and use it before combining this module''s ideas in later work. After bosons/fermions, symmetrization supplies what is needed to address pauli principle.', 1),
  ('15e84b48-db83-4858-8415-e8d6d170afbc', 'debedfa1-d192-4f4a-8b51-cabf50445b5d', 'a3648dfc-6dd7-491f-a415-c189b342f5e4', 'subtopic'::public.curated_course_node_type, 'Pauli principle', 'Pauli principle identifies a specific object, distinction, or relationship within identical particles. Learners need to recognize and use it before combining this module''s ideas in later work. After symmetrization, pauli principle supplies what is needed to address exchange.', 2),
  ('b039cfb8-23eb-4a17-a270-7ebf2bd5d791', 'debedfa1-d192-4f4a-8b51-cabf50445b5d', 'a3648dfc-6dd7-491f-a415-c189b342f5e4', 'subtopic'::public.curated_course_node_type, 'Exchange', 'Exchange identifies a specific object, distinction, or relationship within identical particles. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, exchange carries the completed idea into many-particle structure.', 3),
  ('fbb93e73-39a6-4a96-a55e-e5939dd8fbed', 'debedfa1-d192-4f4a-8b51-cabf50445b5d', null, 'topic'::public.curated_course_node_type, 'Many-particle structure', 'This module builds directly on identical particles and develops many-particle structure. It belongs here because its methods and distinctions are prerequisites for scattering i.', 8),
  ('91fb9f9f-de2d-49f6-8c43-21ed26c8805e', 'debedfa1-d192-4f4a-8b51-cabf50445b5d', 'fbb93e73-39a6-4a96-a55e-e5939dd8fbed', 'subtopic'::public.curated_course_node_type, 'Slater determinants', 'Slater determinants identifies a specific object, distinction, or relationship within many-particle structure. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before second-quantization concepts because that next topic assumes this starting point.', 0),
  ('f6741e86-1442-4b6f-a77c-0c90afe8151c', 'debedfa1-d192-4f4a-8b51-cabf50445b5d', 'fbb93e73-39a6-4a96-a55e-e5939dd8fbed', 'subtopic'::public.curated_course_node_type, 'Second-quantization concepts', 'Second-quantization concepts identifies a specific object, distinction, or relationship within many-particle structure. Learners need to recognize and use it before combining this module''s ideas in later work. After slater determinants, second-quantization concepts supplies what is needed to address mean field.', 1),
  ('b7c94904-fa9c-4182-9984-3a00e5273bfe', 'debedfa1-d192-4f4a-8b51-cabf50445b5d', 'fbb93e73-39a6-4a96-a55e-e5939dd8fbed', 'subtopic'::public.curated_course_node_type, 'Mean field', 'Mean field identifies a specific object, distinction, or relationship within many-particle structure. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, mean field carries the completed idea into scattering i.', 2),
  ('4c170409-4636-45c6-8e19-8a541da8c72d', 'debedfa1-d192-4f4a-8b51-cabf50445b5d', null, 'topic'::public.curated_course_node_type, 'Scattering I', 'This module builds directly on many-particle structure and develops scattering i. It belongs here because its methods and distinctions are prerequisites for scattering ii.', 9),
  ('a4d042b9-2c6c-486b-a94f-fb518a491477', 'debedfa1-d192-4f4a-8b51-cabf50445b5d', '4c170409-4636-45c6-8e19-8a541da8c72d', 'subtopic'::public.curated_course_node_type, 'Cross sections', 'Cross sections identifies a specific object, distinction, or relationship within scattering i. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before born approximation because that next topic assumes this starting point.', 0),
  ('2473f148-b32f-4214-a8c1-a4e766f2b1de', 'debedfa1-d192-4f4a-8b51-cabf50445b5d', '4c170409-4636-45c6-8e19-8a541da8c72d', 'subtopic'::public.curated_course_node_type, 'Born approximation', 'Born approximation makes difficult behavior in scattering i tractable while exposing the assumptions and accuracy limits used by later methods. After cross sections, born approximation supplies what is needed to address partial-wave expansion.', 1),
  ('1c708ce3-48a4-41b7-8a15-b6469e5bbfbc', 'debedfa1-d192-4f4a-8b51-cabf50445b5d', '4c170409-4636-45c6-8e19-8a541da8c72d', 'subtopic'::public.curated_course_node_type, 'Partial-wave expansion', 'Partial-wave expansion identifies a specific object, distinction, or relationship within scattering i. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, partial-wave expansion carries the completed idea into scattering ii.', 2);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('f14ceb4f-048f-4a09-82f7-2f9cf082b009', 'debedfa1-d192-4f4a-8b51-cabf50445b5d', null, 'topic'::public.curated_course_node_type, 'Scattering II', 'This module builds directly on scattering i and develops scattering ii. It belongs here because its methods and distinctions are prerequisites for density operators and open systems.', 10),
  ('1b333321-a912-451d-a81d-b86cc6700050', 'debedfa1-d192-4f4a-8b51-cabf50445b5d', 'f14ceb4f-048f-4a09-82f7-2f9cf082b009', 'subtopic'::public.curated_course_node_type, 'Phase shifts', 'Phase shifts identifies a specific object, distinction, or relationship within scattering ii. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before resonances because that next topic assumes this starting point.', 0),
  ('98ea89fd-5638-4365-8915-765229c390fd', 'debedfa1-d192-4f4a-8b51-cabf50445b5d', 'f14ceb4f-048f-4a09-82f7-2f9cf082b009', 'subtopic'::public.curated_course_node_type, 'Resonances', 'Resonances identifies a specific object, distinction, or relationship within scattering ii. Learners need to recognize and use it before combining this module''s ideas in later work. After phase shifts, resonances supplies what is needed to address low-energy limits.', 1),
  ('19585639-6647-4e50-b938-0f798ac5aa6b', 'debedfa1-d192-4f4a-8b51-cabf50445b5d', 'f14ceb4f-048f-4a09-82f7-2f9cf082b009', 'subtopic'::public.curated_course_node_type, 'Low-energy limits', 'Low-energy limits is a governing quantity in scattering ii, linking local calculations to system-level behavior and offering a consistency check. After resonances, low-energy limits supplies what is needed to address optical theorem.', 2),
  ('5ed26f2b-8bbb-4a00-a982-fdfe01b8c72c', 'debedfa1-d192-4f4a-8b51-cabf50445b5d', 'f14ceb4f-048f-4a09-82f7-2f9cf082b009', 'subtopic'::public.curated_course_node_type, 'Optical theorem', 'Optical theorem provides a formal guarantee or inference rule for scattering ii, allowing later conclusions to be justified rather than inferred from examples alone. As the final topic in this module, optical theorem carries the completed idea into density operators and open systems.', 3),
  ('959b3b83-ac0c-48e3-8738-937860f94dcc', 'debedfa1-d192-4f4a-8b51-cabf50445b5d', null, 'topic'::public.curated_course_node_type, 'Density operators and open systems', 'This culminating module draws on scattering ii and develops density operators and open systems. It belongs last because it requires the earlier tools to be selected, combined, and evaluated rather than used one at a time.', 11),
  ('c16af27d-4548-444c-9a31-1580c73cff4b', 'debedfa1-d192-4f4a-8b51-cabf50445b5d', '959b3b83-ac0c-48e3-8738-937860f94dcc', 'subtopic'::public.curated_course_node_type, 'Mixed states', 'Mixed states identifies a specific object, distinction, or relationship within density operators and open systems. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before entanglement because that next topic assumes this starting point.', 0),
  ('f6551ac9-cace-482a-89ed-f00ef413bbe3', 'debedfa1-d192-4f4a-8b51-cabf50445b5d', '959b3b83-ac0c-48e3-8738-937860f94dcc', 'subtopic'::public.curated_course_node_type, 'Entanglement', 'Entanglement identifies a specific object, distinction, or relationship within density operators and open systems. Learners need to recognize and use it before combining this module''s ideas in later work. After mixed states, entanglement supplies what is needed to address decoherence.', 1),
  ('b7cf2ab7-5b2b-40ba-8352-a5e8898dc7ac', 'debedfa1-d192-4f4a-8b51-cabf50445b5d', '959b3b83-ac0c-48e3-8738-937860f94dcc', 'subtopic'::public.curated_course_node_type, 'Decoherence', 'Decoherence identifies a specific object, distinction, or relationship within density operators and open systems. Learners need to recognize and use it before combining this module''s ideas in later work. After entanglement, decoherence supplies what is needed to address quantum information.', 2),
  ('891788ee-26bd-4ef5-88e6-c66f37e637e3', 'debedfa1-d192-4f4a-8b51-cabf50445b5d', '959b3b83-ac0c-48e3-8738-937860f94dcc', 'subtopic'::public.curated_course_node_type, 'Quantum information', 'Quantum information identifies a specific object, distinction, or relationship within density operators and open systems. Learners need to recognize and use it before combining this module''s ideas in later work. As the final course topic, quantum information requires ideas from the complete path to be integrated and transferred.', 3);
